import { deserializeBigIntsInObject } from "../numbers";
function parseTradesResponse(raw) {
    return {
        trades: raw.trades.map((t) => deserializeBigIntsInObject(t, { handleInts: true })),
        nextCursor: raw.nextCursor,
        hasMore: raw.hasMore,
    };
}
export async function fetchApiTrades(ctx, params) {
    return ctx.api.fetchJson("/v1/trades", {
        query: {
            address: params.address,
            symbol: params.symbol,
            marketAddress: params.marketAddress,
            since: params.since,
            until: params.until,
            actions: params.actions,
            limit: params.limit,
            cursor: params.cursor,
        },
        transform: parseTradesResponse,
    });
}
export async function searchApiTrades(ctx, params) {
    return ctx.api.postJson("/v1/trades/search", params, {
        transform: parseTradesResponse,
    });
}
